sys_script_include.script:
function IsValidScope(strScope)
{
	strScope = GetStringValue(strScope);
	if (strScope == '')
	{
		return false;
	}
	if (strScope.length > 18)
	{
		return false;
	}
	if (strScope.length <= 3)
	{
		return false;
	}	

	var aExceptions = [
		'sn-help-panel',
		'sn-itsm-new-record',
		'sn_list-selector',
		'now-color-picker',
		'now-condition-buil',
		'now-cb-preview',
		'now-dot-walk',
		'now-link-intercept',
		'now-sla-timer',
		'sn-va-web-client',
		'sn-pd-picker'
	];
	if (ArrayValueExists(aExceptions,strScope) == true)
	{
		return true;
	}

	return IsSnakeCase(strScope);
}
